package com.cinenest.identity.internal;

import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import static com.cinenest.identity.internal.CustomerCredentialLifecycle.*;

/** No SQL crosses Identity ownership. This adapter never creates databases, roles or grants. */
final class JdbcCustomerCredentialRepository implements CustomerCredentialRepository {
    final JdbcClient jdbc;final TransactionTemplate tx,independent;
    JdbcCustomerCredentialRepository(JdbcClient jdbc,PlatformTransactionManager manager){this.jdbc=jdbc;tx=new TransactionTemplate(manager);independent=new TransactionTemplate(manager);independent.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    public <T>T transaction(Supplier<T> work){return tx.execute(s->work.get());}
    public void keyContinuity(String version,String lookup,String commands,String encryption,String addressPolicy){transaction(()->{jdbc.sql("SELECT pg_advisory_xact_lock(46104)").query(r->{r.next();return true;});jdbc.sql("INSERT INTO cinenest_identity.customer_key_binding(singleton,key_version,lookup_fingerprint,command_fingerprint,encryption_fingerprint,address_policy) VALUES(true,:version,:lookup,:commands,:encryption,:policy) ON CONFLICT(singleton) DO NOTHING").param("version",version).param("lookup",lookup).param("commands",commands).param("encryption",encryption).param("policy",addressPolicy).update();int same=jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_key_binding WHERE singleton AND key_version=:version AND lookup_fingerprint=:lookup AND command_fingerprint=:commands AND encryption_fingerprint=:encryption AND address_policy=:policy").param("version",version).param("lookup",lookup).param("commands",commands).param("encryption",encryption).param("policy",addressPolicy).query(Integer.class).single();if(same!=1)throw new CustomerCredentialService.Refused(503);return true;});}
    public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query(Instant.class).single();}
    public void lockCommand(UUID id){jdbc.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,46101))").param("key",id.toString()).query(r->{r.next();return true;});}
    public void lockAddress(String key){jdbc.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,46102))").param("key",key).query(r->{r.next();return true;});}
    public Optional<Receipt> receipt(UUID id){return jdbc.sql("SELECT command_id,request_digest,account_id,action,status,credential_epoch FROM cinenest_identity.customer_command WHERE command_id=:id").param("id",id).query((r,n)->new Receipt(r.getObject(1,UUID.class),r.getString(2),r.getObject(3,UUID.class),r.getString(4),r.getInt(5),r.getLong(6))).optional();}
    public Optional<Head> address(String lookup,boolean lock){var ids=jdbc.sql("SELECT account_id FROM cinenest_identity.customer_credential WHERE address_lookup=:lookup AND abandoned_at IS NULL").param("lookup",lookup).query(UUID.class).optional();return ids.flatMap(id->account(id,lock));}
    public Optional<Head> account(UUID id,boolean lock){
        if(lock)jdbc.sql("SELECT account_id FROM cinenest_identity.account WHERE account_id=:id FOR UPDATE").param("id",id).query(UUID.class).optional();
        return jdbc.sql("SELECT c.*,a.revision,a.synthetic,a.eligibility FROM cinenest_identity.customer_credential c JOIN cinenest_identity.account a USING(account_id) WHERE c.account_id=:id"+(lock?" FOR UPDATE OF c":"")).param("id",id).query((r,n)->{
            if(r.getBoolean("synthetic"))throw new CustomerCredentialService.Refused(403);
            State state=State.valueOf(r.getString("state"));
            if(r.getObject("abandoned_at")!=null||r.getString("eligibility").equals("SUSPENDED")||state==State.VERIFIED&&!r.getString("eligibility").equals("ELIGIBLE"))state=State.SUSPENDED;
            return new Head(id,r.getObject("protected_address",UUID.class),r.getString("address_lookup"),r.getBytes("address_ciphertext"),r.getString("address_key_version"),state,r.getLong("revision"),r.getLong("credential_epoch"),r.getString("password_hash"),r.getString("privacy_revision"),r.getString("policy_revision"),r.getString("delivery_revision"),r.getTimestamp("registration_expires_at").toInstant());
        }).optional();
    }
    public Optional<Capability> capability(String digest){return jdbc.sql("SELECT * FROM cinenest_identity.customer_capability WHERE token_digest=:digest").param("digest",digest).query((r,n)->new Capability(new CustomerCredentialLifecycle.Capability(r.getObject("capability_id",UUID.class),r.getObject("account_id",UUID.class),Action.valueOf(r.getString("purpose")),r.getLong("account_revision"),r.getLong("credential_epoch"),r.getString("token_digest"),r.getTimestamp("issued_at").toInstant(),r.getTimestamp("expires_at").toInstant(),r.getObject("consumed_at")!=null||r.getObject("revoked_at")!=null,r.getString("policy_revision"),r.getString("privacy_revision"),r.getString("delivery_revision")),digest)).optional();}
    public UUID admit(UUID command,String action,String subject,boolean hash,CustomerCredentialConfiguration.Settings settings){
        return independent.execute(s->{
            jdbc.sql("SELECT pg_advisory_xact_lock(46103)").query(r->{r.next();return true;});
            long bucket=jdbc.sql("SELECT floor(extract(epoch FROM clock_timestamp())/:seconds)::bigint").param("seconds",settings.windowSeconds()).query(Long.class).single();
            boolean allowed=true;
            for(String key:List.of("GLOBAL",subject.split(":",-1)[0],subject.split(":",-1)[1])){
                int count=jdbc.sql("INSERT INTO cinenest_identity.customer_abuse(action,subject_digest,bucket,attempts) VALUES(:action,:subject,:bucket,1) ON CONFLICT(action,subject_digest,bucket) DO UPDATE SET attempts=customer_abuse.attempts+1 RETURNING attempts").param("action",action).param("subject",key).param("bucket",bucket).query(Integer.class).single();
                if(count>(key.equals("GLOBAL")?settings.limit()*10:settings.limit()))allowed=false;
            }
            int hashes=jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_lease WHERE hashes AND consumed_at IS NULL AND expires_at>clock_timestamp()").query(Integer.class).single();
            if(hash&&hashes>=settings.hashes())allowed=false;
            if(!allowed)return null;
            UUID id=UUID.randomUUID();jdbc.sql("INSERT INTO cinenest_identity.customer_lease(lease_id,command_id,action,hashes,issued_at,expires_at) VALUES(:id,:command,:action,:hash,statement_timestamp(),statement_timestamp()+interval '30 seconds')").param("id",id).param("command",command).param("action",action).param("hash",hash).update();return id;
        });
    }
    public Permit permit(UUID lease,UUID command,UUID account,Action action,String policy){
        if(lease==null)throw new CustomerCredentialService.Refused(429);
        int changed=jdbc.sql("UPDATE cinenest_identity.customer_lease SET account_id=:account WHERE lease_id=:id AND command_id=:command AND action=:action AND consumed_at IS NULL AND expires_at>clock_timestamp() AND (account_id IS NULL OR account_id=:account)").param("id",lease).param("command",command).param("action",action.name()).param("account",account).update();
        if(changed!=1)throw new CustomerCredentialService.Refused(429);
        return jdbc.sql("SELECT issued_at,expires_at,(SELECT count(*) FROM cinenest_identity.customer_lease WHERE hashes AND lease_id<>:id AND consumed_at IS NULL AND expires_at>clock_timestamp()) AS active FROM cinenest_identity.customer_lease WHERE lease_id=:id").param("id",lease).query((r,n)->new Permit(lease,command,account,action,policy,r.getTimestamp(1).toInstant(),r.getTimestamp(2).toInstant(),true,false,r.getInt(3))).single();
    }
    public boolean abandonExpired(Head head,UUID replacementCommand){int changed=jdbc.sql("UPDATE cinenest_identity.customer_credential SET abandoned_at=clock_timestamp() WHERE account_id=:id AND state='PENDING' AND abandoned_at IS NULL AND registration_expires_at<=clock_timestamp()").param("id",head.account()).update();if(changed==1){jdbc.sql("INSERT INTO cinenest_identity.customer_registration_retirement(account_id,replacement_command) VALUES(:id,:command)").param("id",head.account()).param("command",replacementCommand).update();jdbc.sql("UPDATE cinenest_identity.customer_capability SET revoked_at=clock_timestamp() WHERE account_id=:id AND consumed_at IS NULL AND revoked_at IS NULL").param("id",head.account()).update();jdbc.sql("UPDATE cinenest_identity.account SET revision=revision+1 WHERE account_id=:id AND NOT synthetic AND eligibility='INELIGIBLE'").param("id",head.account()).update();return true;}return false;}
    public boolean resendDue(Head head,int seconds){return jdbc.sql("SELECT NOT EXISTS(SELECT 1 FROM cinenest_identity.customer_capability WHERE account_id=:id AND purpose='VERIFY' AND issued_at>clock_timestamp()-make_interval(secs=>:seconds))").param("id",head.account()).param("seconds",seconds).query(Boolean.class).single();}
    public void reissue(Head head,UUID command,String digest,UUID lease,Issue issue){
        var locked=account(head.account(),true).orElseThrow(()->new CustomerCredentialService.Refused(409));if(locked.state()!=State.PENDING||locked.revision()!=head.revision()||locked.epoch()!=head.epoch()||!locked.registrationExpires().isAfter(now())||!issue.expires().isAfter(now()))throw new CustomerCredentialService.Refused(409);
        permit(lease,command,head.account(),Action.REGISTER,head.policy());
        jdbc.sql("UPDATE cinenest_identity.customer_capability SET revoked_at=clock_timestamp() WHERE account_id=:id AND purpose='VERIFY' AND consumed_at IS NULL AND revoked_at IS NULL").param("id",head.account()).update();
        jdbc.sql("INSERT INTO cinenest_identity.customer_capability(capability_id,account_id,purpose,token_digest,account_revision,credential_epoch,policy_revision,privacy_revision,delivery_revision,issued_at,expires_at) VALUES(:id,:account,'VERIFY',:digest,:revision,:epoch,:policy,:privacy,:delivery,clock_timestamp(),:expires)").param("id",issue.capability()).param("account",head.account()).param("digest",issue.digest()).param("revision",head.revision()).param("epoch",head.epoch()).param("policy",head.policy()).param("privacy",head.privacy()).param("delivery",head.delivery()).param("expires",Timestamp.from(issue.expires())).update();
        jdbc.sql("INSERT INTO cinenest_identity.customer_outbox(outbox_id,command_id,account_id,capability_id,purpose,sealed_payload,key_version,policy_revision,expires_at,state) VALUES(:id,:command,:account,:cap,'VERIFY',:payload,:key,:policy,:expires,'PENDING')").param("id",issue.outbox()).param("command",command).param("account",head.account()).param("cap",issue.capability()).param("payload",issue.sealedPayload()).param("key",issue.keyVersion()).param("policy",head.policy()).param("expires",Timestamp.from(issue.expires())).update();
        record(command,digest,head.account(),"REGISTER",202,head.epoch(),UUID.randomUUID(),head.revision());if(jdbc.sql("UPDATE cinenest_identity.customer_lease SET consumed_at=clock_timestamp() WHERE lease_id=:id AND consumed_at IS NULL AND expires_at>clock_timestamp()").param("id",lease).update()!=1)throw new CustomerCredentialService.Refused(429);
    }
    public CustomerCredentialPorts.CommitReceipt commit(Plan plan,Head before,String digest,UUID lease,Issue issue){
        Instant at=now();if(!CustomerCredentialLifecycle.validPlan(plan)||at.isBefore(plan.occurredAt())||Duration.between(plan.occurredAt(),at).getSeconds()>30)throw new CustomerCredentialService.Refused(409);
        if(permit(lease,plan.command(),plan.account(),plan.action(),plan.policyRevision()).expires().isBefore(at))throw new CustomerCredentialService.Refused(429);
        var current=account(plan.account(),true);
        if(plan.expectedState()==State.ABSENT){
            if(current.isPresent())throw new CustomerCredentialService.Refused(409);
            jdbc.sql("INSERT INTO cinenest_identity.account(account_id,synthetic,eligibility,revision) VALUES(:id,false,'INELIGIBLE',:revision)").param("id",plan.account()).param("revision",plan.nextAccountRevision()).update();
            jdbc.sql("INSERT INTO cinenest_identity.customer_credential(account_id,last_command,protected_address,address_lookup,address_ciphertext,address_key_version,state,password_hash,credential_epoch,policy_revision,privacy_revision,delivery_revision,registration_expires_at) VALUES(:id,:command,:address,:lookup,:cipher,:key,'PENDING',:password,0,:policy,:privacy,:delivery,:registrationExpires)").param("id",plan.account()).param("command",plan.command()).param("address",before.address()).param("lookup",before.lookup()).param("cipher",before.sealedAddress()).param("key",before.keyVersion()).param("password",plan.encodedPassword()).param("policy",plan.policyRevision()).param("privacy",plan.privacyRevision()).param("delivery",plan.deliveryRevision()).param("registrationExpires",Timestamp.from(before.registrationExpires())).update();
        }else{
            var locked=current.orElseThrow(()->new CustomerCredentialService.Refused(409));
            if(locked.revision()!=plan.expectedAccountRevision()||locked.epoch()!=plan.previousEpoch()||locked.state()!=plan.expectedState()||!locked.policy().equals(plan.policyRevision())||!locked.privacy().equals(plan.privacyRevision())||!locked.delivery().equals(plan.deliveryRevision()))throw new CustomerCredentialService.Refused(409);
            if(plan.consumeCapability()){
                int consumed=jdbc.sql("UPDATE cinenest_identity.customer_capability SET consumed_at=clock_timestamp(),consumed_command=:command WHERE capability_id=:cap AND account_id=:account AND purpose=:purpose AND account_revision=:revision AND credential_epoch=:epoch AND consumed_at IS NULL AND revoked_at IS NULL AND issued_at<=clock_timestamp() AND expires_at>clock_timestamp() AND policy_revision=:policy AND privacy_revision=:privacy AND delivery_revision=:delivery").param("command",plan.command()).param("cap",plan.capability()).param("account",plan.account()).param("purpose",plan.action().name()).param("revision",plan.expectedAccountRevision()).param("epoch",plan.previousEpoch()).param("policy",plan.policyRevision()).param("privacy",plan.privacyRevision()).param("delivery",plan.deliveryRevision()).update();
                if(consumed!=1)throw new CustomerCredentialService.Refused(409);
            }
            if(plan.action()==Action.VERIFY||plan.action()==Action.RECOVER){
                jdbc.sql("UPDATE cinenest_identity.customer_credential SET last_command=:command,state=:state,password_hash=coalesce(:password,password_hash),credential_epoch=:epoch,verified_at=coalesce(verified_at,clock_timestamp()) WHERE account_id=:id").param("command",plan.command()).param("state",plan.nextState().name()).param("password",plan.encodedPassword(),Types.VARCHAR).param("epoch",plan.nextEpoch()).param("id",plan.account()).update();
                jdbc.sql("UPDATE cinenest_identity.account SET revision=:revision,eligibility='ELIGIBLE' WHERE account_id=:id").param("revision",plan.nextAccountRevision()).param("id",plan.account()).update();
            }
        }
        if(plan.invalidateSessions())jdbc.sql("DELETE FROM cinenest_identity.http_session WHERE principal_name=:principal").param("principal",plan.account().toString()).update();
        if(issue!=null){
            if(!issue.expires().isAfter(at))throw new CustomerCredentialService.Refused(409);
            jdbc.sql("UPDATE cinenest_identity.customer_capability SET revoked_at=clock_timestamp() WHERE account_id=:account AND purpose=:purpose AND consumed_at IS NULL AND revoked_at IS NULL").param("account",plan.account()).param("purpose",issue.purpose()).update();
            jdbc.sql("INSERT INTO cinenest_identity.customer_capability(capability_id,account_id,purpose,token_digest,account_revision,credential_epoch,policy_revision,privacy_revision,delivery_revision,issued_at,expires_at) VALUES(:id,:account,:purpose,:digest,:revision,:epoch,:policy,:privacy,:delivery,:issued,:expires)").param("id",issue.capability()).param("account",plan.account()).param("purpose",issue.purpose()).param("digest",issue.digest()).param("revision",plan.nextAccountRevision()).param("epoch",plan.nextEpoch()).param("policy",plan.policyRevision()).param("privacy",plan.privacyRevision()).param("delivery",plan.deliveryRevision()).param("issued",Timestamp.from(at)).param("expires",Timestamp.from(issue.expires())).update();
            jdbc.sql("INSERT INTO cinenest_identity.customer_outbox(outbox_id,command_id,account_id,capability_id,purpose,sealed_payload,key_version,policy_revision,expires_at,state) VALUES(:id,:command,:account,:cap,:purpose,:payload,:key,:policy,:expires,'PENDING')").param("id",issue.outbox()).param("command",plan.command()).param("account",plan.account()).param("cap",issue.capability()).param("purpose",issue.purpose()).param("payload",issue.sealedPayload()).param("key",issue.keyVersion()).param("policy",plan.policyRevision()).param("expires",Timestamp.from(issue.expires())).update();
        }
        int status=plan.action()==Action.REGISTER||plan.action()==Action.RECOVERY_REQUEST?202:204;
        record(plan.command(),digest,plan.account(),plan.action().name(),status,plan.nextEpoch(),plan.audit(),plan.nextAccountRevision());
        if(jdbc.sql("UPDATE cinenest_identity.customer_lease SET consumed_at=clock_timestamp() WHERE lease_id=:id AND consumed_at IS NULL AND expires_at>clock_timestamp()").param("id",lease).update()!=1)throw new CustomerCredentialService.Refused(429);
        return new CustomerCredentialPorts.CommitReceipt(plan.command(),plan.account(),plan.digest(),plan.audit(),plan.permit(),plan.nextState(),plan.capability(),plan.nextAccountRevision(),plan.nextEpoch(),true,true,true,plan.consumeCapability(),plan.invalidateSessions());
    }
    public Receipt neutral(UUID command,String digest,String action,int status){record(command,digest,null,action,status,0,UUID.randomUUID(),0);return new Receipt(command,digest,null,action,status,0);}
    private void record(UUID command,String digest,UUID account,String action,int status,long epoch,UUID audit,long revision){
        jdbc.sql("INSERT INTO cinenest_identity.customer_command(command_id,request_digest,account_id,action,status,credential_epoch,account_revision) VALUES(:command,:digest,:account,:action,:status,:epoch,:revision)").param("command",command).param("digest",digest).param("account",account,Types.OTHER).param("action",action).param("status",status).param("epoch",epoch).param("revision",revision).update();
        jdbc.sql("INSERT INTO cinenest_identity.customer_audit(event_id,command_id,account_id,action,status,credential_epoch,account_revision) VALUES(:id,:command,:account,:action,:status,:epoch,:revision)").param("id",audit).param("command",command).param("account",account,Types.OTHER).param("action",action).param("status",status).param("epoch",epoch).param("revision",revision).update();
    }
    public void release(UUID id){if(id!=null)independent.executeWithoutResult(s->jdbc.sql("DELETE FROM cinenest_identity.customer_lease WHERE lease_id=:id").param("id",id).update());}
    public void denied(UUID command,String digest,String action,int status){independent.executeWithoutResult(s->{lockCommand(command);if((status==400||status==401)&&receipt(command).isEmpty())record(command,digest,null,action,status,0,UUID.randomUUID(),0);jdbc.sql("INSERT INTO cinenest_identity.security_audit(event_id,actor_id,target_id,event_kind,outcome) VALUES(:id,NULL,NULL,'AUTHENTICATION','DENY')").param("id",UUID.randomUUID()).update();});}
    public List<UUID> pending(int limit,CustomerCredentialConfiguration.Settings settings){if(limit<1||limit>4)throw new IllegalArgumentException();return jdbc.sql("SELECT o.outbox_id FROM cinenest_identity.customer_outbox o JOIN cinenest_identity.customer_capability cap ON cap.capability_id=o.capability_id AND cap.account_id=o.account_id AND cap.purpose=o.purpose JOIN cinenest_identity.customer_credential c ON c.account_id=cap.account_id JOIN cinenest_identity.account a ON a.account_id=c.account_id WHERE o.state='PENDING' AND o.expires_at>clock_timestamp() AND cap.consumed_at IS NULL AND cap.revoked_at IS NULL AND cap.issued_at<=clock_timestamp() AND cap.expires_at>clock_timestamp() AND cap.policy_revision=o.policy_revision AND c.policy_revision=cap.policy_revision AND c.privacy_revision=cap.privacy_revision AND c.delivery_revision=cap.delivery_revision AND c.policy_revision=:currentPolicy AND c.privacy_revision=:currentPrivacy AND c.delivery_revision=:currentDelivery AND cap.account_revision=a.revision AND cap.credential_epoch=c.credential_epoch AND NOT a.synthetic AND ((cap.purpose='VERIFY' AND c.state='PENDING' AND c.abandoned_at IS NULL AND c.registration_expires_at>clock_timestamp() AND a.eligibility='INELIGIBLE') OR(cap.purpose='RECOVER' AND c.state='VERIFIED' AND a.eligibility='ELIGIBLE')) ORDER BY o.created_at,o.outbox_id LIMIT :limit").param("currentPolicy",settings.policy()).param("currentPrivacy",settings.privacy()).param("currentDelivery",settings.delivery()).param("limit",limit).query(UUID.class).list();}
    public boolean deliveryCurrent(UUID id,CustomerCredentialConfiguration.Settings settings){return jdbc.sql("SELECT count(*) FROM cinenest_identity.customer_outbox o JOIN cinenest_identity.customer_capability cap ON cap.capability_id=o.capability_id AND cap.account_id=o.account_id AND cap.purpose=o.purpose JOIN cinenest_identity.customer_credential c ON c.account_id=cap.account_id JOIN cinenest_identity.account a ON a.account_id=c.account_id WHERE o.outbox_id=:id AND o.state='SENDING' AND o.expires_at>clock_timestamp() AND cap.consumed_at IS NULL AND cap.revoked_at IS NULL AND cap.issued_at<=clock_timestamp() AND cap.expires_at>clock_timestamp() AND cap.policy_revision=o.policy_revision AND c.policy_revision=cap.policy_revision AND c.privacy_revision=cap.privacy_revision AND c.delivery_revision=cap.delivery_revision AND c.policy_revision=:policy AND c.privacy_revision=:privacy AND c.delivery_revision=:delivery AND cap.account_revision=a.revision AND cap.credential_epoch=c.credential_epoch AND NOT a.synthetic AND ((cap.purpose='VERIFY' AND c.state='PENDING' AND c.abandoned_at IS NULL AND c.registration_expires_at>clock_timestamp() AND a.eligibility='INELIGIBLE') OR(cap.purpose='RECOVER' AND c.state='VERIFIED' AND a.eligibility='ELIGIBLE'))").param("id",id).param("policy",settings.policy()).param("privacy",settings.privacy()).param("delivery",settings.delivery()).query(Integer.class).single()==1;}
    public Optional<Outbox> claim(UUID id,CustomerCredentialConfiguration.Settings settings){return independent.execute(s->{
        var actor=jdbc.sql("SELECT account_id FROM cinenest_identity.customer_outbox WHERE outbox_id=:id").param("id",id).query(UUID.class).optional();if(actor.isEmpty())return Optional.empty();account(actor.get(),true);
        var rows=jdbc.sql("UPDATE cinenest_identity.customer_outbox SET state='SENDING' WHERE outbox_id=:id AND state='PENDING' AND expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM cinenest_identity.customer_capability cap JOIN cinenest_identity.customer_credential c USING(account_id) JOIN cinenest_identity.account a USING(account_id) WHERE cap.capability_id=customer_outbox.capability_id AND cap.account_id=customer_outbox.account_id AND cap.purpose=customer_outbox.purpose AND cap.policy_revision=customer_outbox.policy_revision AND c.policy_revision=cap.policy_revision AND c.privacy_revision=cap.privacy_revision AND c.delivery_revision=cap.delivery_revision AND c.policy_revision=:currentPolicy AND c.privacy_revision=:currentPrivacy AND c.delivery_revision=:currentDelivery AND cap.account_revision=a.revision AND cap.credential_epoch=c.credential_epoch AND cap.consumed_at IS NULL AND cap.revoked_at IS NULL AND cap.issued_at<=clock_timestamp() AND cap.expires_at>clock_timestamp() AND NOT a.synthetic AND ((cap.purpose='VERIFY' AND c.state='PENDING' AND c.abandoned_at IS NULL AND c.registration_expires_at>clock_timestamp() AND a.eligibility='INELIGIBLE') OR(cap.purpose='RECOVER' AND c.state='VERIFIED' AND a.eligibility='ELIGIBLE'))) RETURNING *").param("id",id).param("currentPolicy",settings.policy()).param("currentPrivacy",settings.privacy()).param("currentDelivery",settings.delivery()).query((r,n)->new Outbox(id,r.getObject("command_id",UUID.class),r.getObject("account_id",UUID.class),r.getObject("capability_id",UUID.class),r.getString("purpose"),r.getBytes("sealed_payload"),r.getString("key_version"),r.getString("policy_revision"),r.getTimestamp("expires_at").toInstant(),r.getString("state"))).list();return rows.stream().findFirst();});}
    public void deliveryResult(UUID id,String state){if(!Set.of("ACCEPTED","UNKNOWN").contains(state))throw new IllegalArgumentException();independent.executeWithoutResult(s->jdbc.sql("UPDATE cinenest_identity.customer_outbox SET state=:state WHERE outbox_id=:id AND state='SENDING'").param("state",state).param("id",id).update());}
}
